function canWrite(session?:Session){const u=session?.user;return u?.role==='administrator'||u?.role==='operator'||u?.roles?.some(r=>['administrator','operator'].includes(r))||u?.permissions?.includes('messages:produce')}
function TopicDetails({clusterId,topic,session,onDeleted,onPlan}:{clusterId:string;topic:string;session?:Session;onDeleted?:()=>void;onPlan?:()=>void}){const initialTab=route.useSearch().tab;const [tab,setTab]=useState<string>(initialTab??'Overview');const query=useApi<TopicDetail>(`/clusters/${clusterId}/topics/${encodeURIComponent(topic)}`);const tabs=topicTabs;const detail=query.data?.data;return <><TopicAdministration clusterId={clusterId} topic={topic} session={session} onDeleted={onDeleted}/><div className="tabs">{tabs.map(x=><button key={x} className={tab===x?'active':''} onClick={()=>setTab(x)}>{x}</button>)}</div>{tab==='Messages'?<Messages clusterId={clusterId} initialTopic={topic} canProduce={!!canWrite(session)}/>:tab==='Metrics'?<section className="panel"><VisibleChart clusterId={clusterId} metric={`topic:${topic}`}/></section>:tab==='Distribution'?<TopicDistribution clusterId={clusterId} topic={topic} onPlan={onPlan}/>:tab==='Balance'?<Balance clusterId={clusterId} go={()=>onPlan?.()}/>:tab==='Consumers'?<TopicConsumers clusterId={clusterId} topic={topic}/>:tab==='Configuration'?<TopicConfiguration clusterId={clusterId} topic={topic}/>:tab==='Audit'?<ResourcePage clusterId={clusterId} page="audit"/>:query.isLoading||query.error||!detail?<section className="panel"><ErrorBox error={query.error}/>{query.isLoading?<Loading/>:!query.error&&<Empty/>}</section>:tab==='Partitions'?<section className="panel"><PanelTitle title={`${topic} · Partitions`} subtitle="Leader, replica placement, in-sync state and offsets per partition."/><PartitionTable partitions={detail.partitions}/></section>:<TopicOverview clusterId={clusterId} topic={detail} onTab={setTab}/>}</>}
function ObjectTable({data}:{data:Record<string,unknown>[]}){const keys=Array.from(new Set(data.slice(0,10).flatMap(x=>Object.keys(x)))).slice(0,10);const columns:ColumnDef<Record<string,unknown>>[]=keys.map(key=>({accessorKey:key,header:key.replace(/([A-Z])/g,' $1'),cell:({getValue})=>{const v=getValue();return typeof v==='object'?<span className="mono">{pretty(v)}</span>:key.toLowerCase().includes('state')?<Status value={String(v)}/>:key.toLowerCase().includes('size')?bytes(typeof v==='number'?v:null):String(v??'—')}}));return <DataTable data={data} columns={columns}/>}
function ResourcePage({clusterId,page}:{clusterId:string;page:string}){const path=page==='settings'?'configuration':page;const query=useApi<unknown>(`/clusters/${clusterId}/${path}`);const [q,setQ]=useState('');const data=query.data?.data;const rows=Array.isArray(data)?data:[];const filtered=rows.filter(x=>JSON.stringify(x).toLowerCase().includes(q.toLowerCase()));return <section className="panel"><div className="table-toolbar"><div className="search-input"><Search size={15}/><input placeholder="Filter records…" value={q} onChange={e=>setQ(e.target.value)} aria-label="Filter records"/></div><span className="table-count">{rows.length} records</span><div className="toolbar-right"><Download data={data??[]} name={`${page}.json`}/></div></div><ErrorBox error={query.error}/>{query.isLoading?<Loading/>:Array.isArray(data)?<ObjectTable data={filtered}/>:data?<div className="detail-grid">{Object.entries(data as Record<string,unknown>).map(([k,v])=><div key={k}><span>{k}</span><strong>{typeof v==='object'?pretty(v):String(v??'Unavailable')}</strong></div>)}</div>:!query.error&&<Empty/>}<div className="panel-bottom"><span>Authoritative cluster inventory</span><span>Mutations require action-specific permissions</span></div></section>}
function Balance({clusterId,go}:{clusterId:string;go:(s:string)=>void}){const capabilities=useApi<ClusterCapabilities>(`/clusters/${clusterId}/capabilities`);const query=useApi<{dimensions:string[];distribution:{broker:number;replicas:number;leaders:number;bytes?:number}[];capacityKnown:boolean;capacity?:BrokerCapacity}>(`/clusters/${clusterId}/balance`);const [dimension,setDimension]=useState('replicas');const d=query.data?.data;const max=Math.max(...(d?.distribution??[]).map(x=>Number(x[dimension as keyof typeof x]??0)),1);const counts=(d?.distribution??[]).map(x=>Number(x[dimension as keyof typeof x]??0));const mean=counts.reduce((a,b)=>a+b,0)/Math.max(counts.length,1);const cv=mean?Math.sqrt(counts.reduce((s,x)=>s+(x-mean)**2,0)/Math.max(counts.length,1))/mean:0;return <><CapabilityNotice capabilities={capabilities.data?.data} error={capabilities.error}/><div className="tabs">{['replicas','leaders','bytes','throughput'].map(x=><button key={x} onClick={()=>setDimension(x)} className={dimension===x?'active':''}>{x[0].toUpperCase()+x.slice(1)}</button>)}</div><section className="panel"><PanelTitle title="Distribution analysis" subtitle={`Comparing broker ${dimension} · source: Kafka Admin API`} action={<button className="button primary" disabled={!reassignmentAccess(capabilities.data?.data).canPlan} onClick={()=>go('reassignments')}>Generate plan <ArrowRight size={14}/></button>}/><ErrorBox error={query.error}/>{query.isLoading?<Loading/>:d&&d.dimensions.includes(dimension)?<><div className="balance-summary"><div><span>Distribution skew</span><strong>{(cv*100).toFixed(1)}%</strong><small>Coefficient of variation</small></div><div><span>Mean per broker</span><strong>{mean.toFixed(1)}</strong><small>{dimension}</small></div><CapacityTile capacity={d.capacity}/></div><CapacityDetail capacity={d.capacity}/><div className="broker-bars">{d.distribution.map((b,i)=><div className="broker-bar-row" key={b.broker}><span><i className="good-dot"/>broker-{b.broker}</span><div className="bar-track"><div style={{width:`${Number(b[dimension as keyof typeof b]??0)/max*100}%`,background:`var(--broker-${i%3})`}}/></div><strong>{b[dimension as keyof typeof b]}<small>{dimension}</small></strong></div>)}</div><div className="panel-bottom">Replica placement is independent of broker capacity.<span>Review rack constraints before execution.</span></div></>:d?<Empty text={`${dimension==='bytes'?'Log size':'Throughput'} data is unavailable. Configure a metrics source to enable this analysis.`}/>:!query.error&&<Empty/>}</section><section className="panel"><PanelTitle title="Plan with context" subtitle="Safety checks run again at execution time."/><div className="plan-guidance"><Shield size={20}/><div><strong>Review the exact replica assignments before approving.</strong><p>Plans capture the current cluster state. Stale plans are rejected by the backend. Rack awareness, throttling and durable worker recovery are part of the execution workflow.</p></div><button className="button" onClick={()=>go('reassignments')}>Open reassignments <ArrowRight size={14}/></button></div></section></>}
type Plan=ThrottlePlan&{changes:{topic:string;partition:number;before:number[];after:number[]}[];before:unknown;after:unknown;createdAt:string;progress?:number};
function Reassignments({clusterId,session}:{clusterId:string;session?:Session}){const tz=useTimeZone();const {planTopic}=route.useSearch();const capabilityEvery=useEssentialInterval(15_000);const capabilities=useApi<ClusterCapabilities>(`/clusters/${clusterId}/capabilities`,true,capabilityEvery);const {canPlan,canRun:allowed}=reassignmentAccess(capabilities.data?.data);const blockedReason=capabilities.data?.data?.reason||'Running plans is disabled until cluster capability is known.';const planListEvery=useEssentialInterval(5_000);const query=useApi<Plan[]>(`/clusters/${clusterId}/rebalances`,true,planListEvery);const [topics,setTopics]=useState<string[]>([]);useEffect(()=>{if(planTopic)setTopics(old=>old.includes(planTopic)?old:[...old,planTopic])},[planTopic]);const [removing,setRemoving]=useState<Plan|null>(null);const [throttle,setThrottle]=useState('10485760');const [rack,setRack]=useState(true);const [plan,setPlan]=useState<Plan|null>(null);const [confirm,setConfirm]=useState(false);const [notice,setNotice]=useState('');const [busy,setBusy]=useState(false);const planDetailEvery=useEssentialInterval(3_000,!!plan);const detail=useApi<Plan>(`/clusters/${clusterId}/rebalances/${plan?.id}`,!!plan,planDetailEvery);const current=detail.data?.data??plan;const [validation,setValidation]=useState<{valid:boolean;planHash:string;partitions:number;capacityKnown:boolean;warnings:string[]}|null>(null);async function dryRun(){if(!current)return;setBusy(true);setValidation(null);try{const r=await api<{valid:boolean;planHash:string;partitions:number;capacityKnown:boolean;warnings:string[]}>(`/clusters/${clusterId}/rebalances/${current.id}/dry-run`,{method:'POST',body:JSON.stringify({confirmation:true,planHash:current.planHash})});setValidation(r.data)}catch(e){setNotice((e as Error).message)}finally{setBusy(false)}}async function action(kind:string){if(!current)return;setBusy(true);try{const result=await api<Plan>(`/clusters/${clusterId}/rebalances/${current.id}/${kind}`,{method:'POST',body:JSON.stringify({confirmation:true,planHash:current.planHash})});setPlan(result.data);setNotice(`${kind==='execute'?'Execution':kind==='cancel'?'Cancellation':'Rollback'} requested.`);setConfirm(false);query.refetch();detail.refetch()}catch(e){setNotice((e as Error).message)}finally{setBusy(false)}}return <><CapabilityNotice capabilities={capabilities.data?.data} error={capabilities.error}/><section className="panel plan-builder"><PanelTitle title="Plan a safe reassignment" subtitle="Generate, inspect, and explicitly approve. No partition moves until execution."/><form onSubmit={async e=>{e.preventDefault();setBusy(true);try{const response=await api<Plan>(`/clusters/${clusterId}/rebalances`,{method:'POST',body:JSON.stringify({topics,throttleBytesPerSec:Number(throttle),rackAware:rack})});setPlan(response.data);query.refetch()}catch(e){setNotice((e as Error).message)}finally{setBusy(false)}}}><label>Topics<TopicPicker clusterId={clusterId} label="Topics" selected={topics} onChange={t=>setTopics(old=>old.includes(t)?old.filter(x=>x!==t):[...old,t])}/><span className="topic-chips">{topics.map(t=><span key={t}>{t}<button type="button" aria-label={`Remove ${t}`} onClick={()=>setTopics(old=>old.filter(x=>x!==t))}><X size={11}/></button></span>)}</span></label><label>Throttle · bytes / second<input type="number" min="1" value={throttle} onChange={e=>setThrottle(e.target.value)}/></label><label className="checkbox-label"><input type="checkbox" checked={rack} onChange={e=>setRack(e.target.checked)}/>Honor rack awareness</label><button className="button primary" disabled={busy||!topics.length||!canWrite(session)||!canPlan}><GitBranch size={15}/>{busy?'Working…':'Generate plan'}</button></form></section>{current&&<section className="panel plan-review"><PanelTitle title={`Review plan · ${current.id}`} subtitle={`Created ${tz.dateTime(current.createdAt)}`} badge={current.state}/><PlanChanges plan={current}/>{typeof current.progress==='number'&&<div className="plan-progress"><span>Moved partitions</span><progress max={100} value={current.progress} aria-label="Reassignment progress"/><strong>{current.progress}%</strong></div>}{validation&&validation.planHash===current.planHash&&<div className="dry-run-result" role="status"><strong>{validation.valid?'Dry run valid':'Dry run rejected'}</strong><span>{validation.partitions} partitions checked</span>{!validation.capacityKnown&&<p>Broker capacity is unknown. This plan does not establish capacity safety.</p>}{validation.warnings?.map((warning,i)=><p key={i}>{warning}</p>)}</div>}{current.state==='running'&&<ThrottleControl clusterId={clusterId} plan={current} canWrite={canWrite(session)} allowed={allowed} onChange={()=>{detail.refetch();query.refetch()}}/>}<p className="muted plan-note">Cancellation stops further moves. Use rollback to request restoration of the original assignments.</p><div className="plan-approval"><label><input type="checkbox" checked={confirm} onChange={e=>setConfirm(e.target.checked)}/>I reviewed the replica changes and approve this exact plan.</label><span className="mono">Hash {current.planHash?.slice(0,16)}</span>{/draft|planned|ready/i.test(current.state)&&<button className="button" disabled={busy||!canWrite(session)||!canPlan} onClick={dryRun}>Validate dry run</button>}<button className="button primary" disabled={!confirm||busy||!canWrite(session)||!allowed||!/draft|planned|ready/i.test(current.state)} onClick={()=>action('execute')} title={allowed?undefined:blockedReason} aria-describedby={allowed?undefined:'execute-blocked'}>Execute plan <ArrowRight size={14}/></button>{!allowed&&canPlan&&<span id="execute-blocked" className="muted execute-blocked">Plans can be validated, but not run. {blockedReason}</span>}<button className="button" disabled={!confirm||busy||!canWrite(session)||!canPlan} onClick={()=>action('rollback')}>Request rollback</button>{/queued|running/i.test(current.state)&&<button className="button danger-button" disabled={!confirm||busy||!canWrite(session)||!allowed} onClick={()=>action('cancel')}>Cancel reassignment</button>}</div></section>}<section className="panel"><PanelTitle title="Operation history" subtitle="Durable plans and worker progress"/><ErrorBox error={query.error}/>{query.isLoading?<Loading/>:<div className="operation-list">{query.data?.data.length?query.data.data.map(x=><div key={x.id}><button onClick={()=>setPlan(x)}><GitBranch size={17}/><strong>{x.id}</strong><span>{x.topics?.join(', ')}</span><Status value={x.state}/><ChevronRight size={14}/></button><button className="icon-button" aria-label={`Delete plan ${x.id}`} title={activePlan(x)?'Active reassignments cannot be deleted':'Delete plan'} disabled={busy||!canWrite(session)||activePlan(x)} onClick={()=>setRemoving(x)}><Trash2 size={14}/></button></div>):<Empty text="No reassignment plans yet."/>}</div>}</section><Dialog.Root open={!!removing} onOpenChange={o=>{if(!o)setRemoving(null)}}><Dialog.Portal><Dialog.Overlay className="dialog-overlay"/><Dialog.Content className="dialog"><Dialog.Title>Delete reassignment plan</Dialog.Title><Dialog.Description>Removes this plan from operation history. Audit log entries are kept.</Dialog.Description><Dialog.Close className="dialog-close" aria-label="Close"><X size={18}/></Dialog.Close><form onSubmit={async e=>{e.preventDefault();if(!removing)return;setBusy(true);try{await api(`/clusters/${clusterId}/rebalances/${encodeURIComponent(removing.id)}`,{method:'DELETE'});if(plan?.id===removing.id)setPlan(null);setNotice('Plan deleted.');setRemoving(null);query.refetch()}catch(e){setNotice((e as Error).message)}finally{setBusy(false)}}}><div className="review-destination">Plan<strong>{removing?.id}</strong></div><div className="review-destination">Topics<strong>{removing?.topics?.join(', ')}</strong></div><button className="button danger-button" disabled={busy}>{busy?'Deleting…':'Confirm deletion'}</button></form></Dialog.Content></Dialog.Portal></Dialog.Root>{notice&&<div className="toast" role="status" onClick={()=>setNotice('')}>{notice}<X size={14}/></div>}</>}
function Replicas({ids,other,kind}:{ids:number[];other:number[];kind:'before'|'after'}){return <span className="replica-list">{ids.map((b,i)=><span key={b} className={other.includes(b)?undefined:kind==='after'?'added':'removed'} title={i===0?'Preferred leader':undefined}>{b}{i===0&&<i aria-label="leader">•</i>}</span>)}</span>}
function PlanChanges({plan}:{plan:Plan}){const changes=plan.changes??[];return <><div className="plan-changes-head"><strong>{changes.length} partition{changes.length===1?'':'s'} change</strong><span className="muted">First replica is the preferred leader · <b className="added">added</b> · <s className="removed">removed</s></span></div>{changes.length?<div className="table-scroll plan-changes"><table><thead><tr><th scope="col">Topic</th><th scope="col">Partition</th><th scope="col">Replicas before</th><th scope="col" aria-hidden="true"/><th scope="col">Replicas after</th></tr></thead><tbody>{changes.map(c=><tr key={`${c.topic}-${c.partition}`}><td data-label="Topic">{c.topic}</td><td data-label="Partition">{c.partition}</td><td data-label="Replicas before"><Replicas ids={c.before} other={c.after} kind="before"/></td><td aria-hidden="true" className="plan-arrow"><ArrowRight size={13}/></td><td data-label="Replicas after"><Replicas ids={c.after} other={c.before} kind="after"/></td></tr>)}</tbody></table></div>:<Empty text="Replica placement is already balanced for the selected topics."/>}<details className="plan-json"><summary>Reassignment JSON <span className="muted">· before and after, for review or export</span></summary><div className="plan-json-grid">{([['Before',plan.before],['After',plan.after]] as const).map(([label,value])=><div key={label}><div className="plan-json-bar"><span>{label}</span><Download data={value} name={`plan-${plan.id}-${label.toLowerCase()}.json`} label={`Export ${label.toLowerCase()} JSON`}/></div><pre>{pretty(value)}</pre></div>)}</div></details></>}
const activePlan=(p:Plan)=>/^(queued|running|rollback-queued)$/.test(p.state)||!!p.cleanupPending;
function Metrics({clusterId}:{clusterId:string}){const catalog=useApi<MetricDefinition[]>(`/clusters/${clusterId}/metrics/catalog`);const [filter,setFilter]=useState('');const [category,setCategory]=useState('all');const [selected,setSelected]=useState<string[]>([]);const [range,setRange]=useState<MetricRange>('1h');const definitions=catalog.data?.data??[];const categories=Array.from(new Set(definitions.map(x=>x.category)));const filtered=definitions.filter(x=>(category==='all'||x.category===category)&&x.title.toLowerCase().includes(filter.toLowerCase()));return <><div className="monitoring-note"><Activity size={16}/><span>Native metrics · visible charts only · bounded queries · source timestamps retained</span><div className="segmented range-picker" role="group" aria-label="Time range">{(Object.keys(metricRanges) as MetricRange[]).map(r=><button key={r} className={range===r?'selected':''} aria-pressed={range===r} onClick={()=>setRange(r)}>{r}</button>)}</div></div><section className="panel"><div className="table-toolbar"><div className="search-input"><Search size={15}/><input aria-label="Search metrics" placeholder="Search metric catalog…" value={filter} onChange={e=>setFilter(e.target.value)}/></div><select aria-label="Metric category" value={category} onChange={e=>setCategory(e.target.value)}><option value="all">All categories</option>{categories.map(x=><option key={x}>{x}</option>)}</select><span className="table-count">{definitions.length} configured queries</span></div><ErrorBox error={catalog.error}/><div className="metric-selector">{filtered.map(x=><button className={selected.includes(x.id)?'selected':''} key={x.id} onClick={()=>setSelected(old=>old.includes(x.id)?old.filter(id=>id!==x.id):old.length<8?[...old,x.id]:old)}><Activity size={13}/><span>{x.title}</span><small>{x.kind}</small>{selected.includes(x.id)&&<Check size={13}/>}</button>)}</div></section><div className="metric-grid">{(selected.length?selected:['throughput','consumer-lag','replication','storage']).map(metric=><section className="panel" key={metric}><PanelTitle title={definitions.find(x=>x.id===metric)?.title??metric[0].toUpperCase()+metric.slice(1).split('-').join(' ')} subtitle="Configured metrics datasource"/><VisibleChart clusterId={clusterId} metric={metric} range={range}/></section>)}</div></>}
function LoginPage(){const navigate=useNavigate();return <Login onSuccess={()=>{client.invalidateQueries({queryKey:['/auth/session']});navigate({to:'/',search:{}})}}/>}
const rootRoute=createRootRoute({component:()=> <Outlet/>});const loginRoute=createRoute({getParentRoute:()=>rootRoute,path:'login',component:LoginPage});const route=createRoute({getParentRoute:()=>rootRoute,path:'$',validateSearch:(search:SearchSchemaInput & Record<string,unknown>)=>validateTopicSearch(search),component:App});const router=createRouter({routeTree:rootRoute.addChildren([loginRoute,route]),defaultNotFoundComponent:()=><ErrorPage code={404} fullPage/>,defaultErrorComponent:({error})=><ErrorPage code={500} fullPage detail={error.message}/>});declare module '@tanstack/react-router'{interface Register{router:typeof router}}
createRoot(document.getElementById('root')!).render(<React.StrictMode><QueryClientProvider client={client}><RefreshProvider><RouterProvider router={router}/></RefreshProvider></QueryClientProvider></React.StrictMode>);
